environment.BASH_FUNC_switchml%%:
() {  typeset swfound=1;
 if [ "${MODULES_USE_COMPAT_VERSION:-0}" = '1' ]; then
 typeset swname='main';
 if [ -e /cm/local/apps/environment-modules/4.5.3//libexec/modulecmd.tcl ]; then
 typeset swfound=0;
 unset MODULES_USE_COMPAT_VERSION;
 fi;
 else
 typeset swname='compatibility';
 if [ -e /cm/local/apps/environment-modules/4.5.3//libexec/modulecmd-compat ]; then
 typeset swfound=0;
 MODULES_USE_COMPAT_VERSION=1;
 export MODULES_USE_COMPAT_VERSION;
 fi;
 fi;
 if [ $swfound -eq 0 ]; then
 echo "Switching to Modules $swname version";
 source /cm/local/apps/environment-modules/4.5.3//init/bash;
 else
 echo "Cannot switch to Modules $swname version, command not found";
 return 1;
 fi
}

environment.BASH_FUNC__ms_helper_configure%%:
() {  cp ${ManySpacks_HOME}/packages/$CLUSTER.packages.yaml ${MS_TARG}/${profile}/spack/etc/spack/packages.yaml;
 cp -r ${ManySpacks_HOME}/spackages ${MS_TARG}/${profile}/;
 echo -e "repos:\n- ${MS_TARG}/${profile}/spackages" > ${MS_TARG}/${profile}/spack/etc/spack/repos.yaml;
 if [ ${CLUSTER} = sbrinz ]; then
 cp ${ManySpacks_HOME}/concretizer.yaml ${MS_TARG}/${profile}/spack/etc/spack/concretizer.yaml;
 fi;
 if [ -f ${ManySpacks_HOME}/compilers.yaml ]; then
 mkdir -p ${MS_TARG}/${profile}/spack/etc/spack/linux;
 cp ${ManySpacks_HOME}/compilers.yaml ${MS_TARG}/${profile}/spack/etc/spack/linux/compilers.yaml;
 fi;
 local currdir=$PWD;
 cd ${MS_TARG}/${profile}/spack;
 git checkout develop;
 git pull;
 if [ -f ${ManyTests_HOME}/results.txt ] && [ ! "${profile}" = "ManyTestsSpack" ]; then
 echo -e "${GREEN}[I]: ${CYAN}ManyTests${GREEN} detected: Checkout to a safe tag${NC}";
 local checkpoint=$(echo "$(grep SUCCESS ${ManyTests_HOME}/results.txt | tail -1)" | cut -c1-40);
 git config advice.detachedHead false;
 git checkout $checkpoint;
 fi;
 cd $currdir
}

environment.BASH_FUNC__ms_helper_update%%:
() {  echo -e "${GREEN}[I]: Updating Spack branch ${CYAN}${profile}${NC}";
 ( _ms_helper_configure );
 echo -e "${GREEN}[I]: Done${NC}"
}

environment.BASH_FUNC_manyspacks%%:
() {  if [ ! "$NOCOLOR" = "TRUE" ]; then
 local NC='\033[0m';
 local RED='\033[0;31m';
 local GREEN='\033[0;32m';
 local YELLOW='\033[33m';
 local CYAN='\033[0;36m';
 local MAGENTA='\033[0;95m';
 fi;
 while [ $# -gt 0 ]; do
 case "$1" in 
 version)
 echo -e "${GREEN}[I]: ${CYAN}ManySpacks 0.3.2${NC}";
 shift
 ;;
 help | -h | --help)
 echo -e "${GREEN}[I]: Usage: manyspacks [OPTION]...${CYAN}
        help            Show this message
        create          Create a new Spack branch with the specified name
        autosetup       Set up the specified Spack branch (requires ManyScripts support)
        load            Load the Spack branch with the given name
        unload          Unload the current branch
        reload          It reloads the current active branch and resets some environment variables
        update          Update Spack and config files in the specified branch
        updateAll       Perform update on all Spack branches
        refresh         Update legacy branch to current standard
        backup          Back up the Spack branch with the given name
        restore         Restore the Spack branch with the given name
        list            Find all available Spack branches
        listBackups     Find all available Spack branch backups
        remove          Remove the Spack branch with the given name
        removeBackup    Remove the Spack branch backup with the given name
        which           Show the active branch in the current terminal session
        cd              Change PWD to the target branch
        pkgload         Load the package for the specified branch and the specified package
        pkgunload       Unload the package for the specified branch and the specified package
        pkgunloadAll    Unload all packages, including the one loaded by Spack directly
        pkglistLoaded   Show all loaded packages
        pkginstall      Install the specified package into the specified branch
        envinstall      Install the specified packages inside a Spack environment into the specified branch
        pkguninstall    Uninstall the specified package in the specified branch
        pkglocate       Return the location of the specified package in the specified branch
        shell           Execute the given command for the specified branch${NC}";
 shift
 ;;
 create)
 local profile="${2}Spack";
 if [ -d "${MS_TARG}/${profile}" ]; then
 echo -e "${RED}[E]: Branch already exists${NC}";
 return;
 fi;
 if [[ ${profile} == *['!'@#\$%^\&*()+\/]* ]]; then
 echo -e "${RED}[E]: Name contains special characters${NC}";
 return;
 else
 if [ -z "${2}" ]; then
 echo -e "${RED}[E]: Name is empty${NC}";
 return;
 fi;
 fi;
 echo -e "${GREEN}[I]: Creating Spack branch ${CYAN}${profile}${NC}";
 mkdir -p ${MS_TARG}/${profile};
 git clone -c feature.manyFiles=true https://github.com/spack/spack.git ${MS_TARG}/${profile}/spack/;
 mkdir ${MS_TARG}/${profile}/.spack;
 ( _ms_helper_configure );
 echo -e "${GREEN}[I]: Done${NC}";
 if ${AUTOLOAD}; then
 manyspacks load ${profile};
 fi;
 shift;
 shift
 ;;
 autosetup)
 local profile="${2}";
 if [ ! -d "${ManyScripts_HOME}/Clusters/${CLUSTER}" ]; then
 echo -e "${RED}[E]: ${CYAN}ManyScripts${RED} support for Cluster ${CYAN}${CLUSTER}${RED} not found${NC}";
 return;
 fi;
 echo -e "${GREEN}[I]: Setting up Spack branch ${CYAN}${profile}${NC}";
 rm -rf ${ManySpacks_HOME}/Clusters/${CLUSTER}/compilers/.spack-env;
 rm -rf ${ManySpacks_HOME}/Clusters/${CLUSTER}/compilers/spack.lock;
 if [ "${MS_CURR}" = "${profile}" ]; then
 spack compiler find;
 spack env activate ${ManyScripts_HOME}/Clusters/${CLUSTER}/compilers;
 spack concretize -j32 -f;
 spack install -j32;
 spack env deactivate;
 spack load $(cat ${ManyScripts_HOME}/Clusters/${CLUSTER}/compilers/compilers.txt);
 spack compiler find;
 spack unload -a;
 rm -rf ${ManySpacks_HOME}/Clusters/${CLUSTER}/compilers/.spack-env;
 rm -rf ${ManySpacks_HOME}/Clusters/${CLUSTER}/compilers/spack.lock;
 else
 if [ -n "${MS_CURR}" ]; then
 echo -e "${YELLOW}[W]: Active branch ${CYAN}${MS_CURR}${YELLOW} detected${NC}";
 echo -e "${RED}[E]: Environment not clean enough${NC}";
 return;
 fi;
 ( manyspacks envinstall ${profile} ${ManyScripts_HOME}/Clusters/${CLUSTER}/compilers && manyspacks shell ${profile} "spack load $(cat ${ManyScripts_HOME}/Clusters/${CLUSTER}/compilers/compilers.txt) && spack compiler find" );
 fi;
 rm -rf ${ManySpacks_HOME}/Clusters/${CLUSTER}/compilers/.spack-env;
 rm -rf ${ManySpacks_HOME}/Clusters/${CLUSTER}/compilers/spack.lock;
 echo -e "${GREEN}[I]: Done${NC}";
 shift;
 shift
 ;;
 load)
 local profile="$2";
 echo -e "${GREEN}[I]: Loading branch ${CYAN}${profile}${NC}";
 if ! _ms_helper_branchTest; then
 return;
 fi;
 if [ "${MS_CURR}" = "${profile}" ]; then
 echo -e "${YELLOW}[W]: Branch ${CYAN}${profile}${YELLOW} already loaded${NC}";
 return;
 fi;
 if [ -n "${MS_CURR}" ]; then
 echo -e "${YELLOW}[W]: Active branch ${CYAN}${MS_CURR}${YELLOW} detected${NC}";
 echo -e "${GREEN}[I]: Performing auto unloading${NC}";
 _ms_helper_resetEnv;
 fi;
 _ms_helper_load;
 echo -e "${GREEN}[I]: Done${NC}";
 shift;
 shift
 ;;
 unload)
 if [ -z "${MS_CURR}" ]; then
 echo -e "${RED}[E]: No active branch found${NC}";
 return;
 else
 echo -e "${GREEN}[I]: Unloading current branch ${CYAN}${MS_CURR}${NC}";
 _ms_helper_resetEnv;
 fi;
 echo -e "${GREEN}[I]: Done${NC}";
 shift
 ;;
 reload)
 echo -e "${GREEN}[I]: Reloading the last profile${NC}";
 if [ -z "${MS_CURR}" ]; then
 echo -e "${RED}[E]: There is nothing to reload${NC}";
 return;
 fi;
 local profile=$MS_CURR;
 _ms_helper_resetEnv;
 _ms_helper_load;
 echo -e "${GREEN}[I]: ${CYAN}${MS_CURR} ${GREEN}loaded${NC}";
 shift
 ;;
 update)
 local profile="$2";
 if ! _ms_helper_branchTest; then
 return;
 fi;
 _ms_helper_update;
 shift;
 shift
 ;;
 updateAll)
 for profile in $(ls ${MS_TARG} | sed "s~Backups~~g");
 do
 _ms_helper_update;
 done;
 shift
 ;;
 refresh)
 local profile="$2";
 if ! _ms_helper_branchTest; then
 return;
 fi;
 cp ${MS_TARG}/${profile}/.spack/*.yaml ${MS_TARG}/${profile}/spack/etc/spack/;
 cp -r ${MS_TARG}/${profile}/.spack/linux ${MS_TARG}/${profile}/spack/etc/spack/;
 shift;
 shift
 ;;
 backup)
 local profile="$2";
 if ! _ms_helper_branchTest; then
 return;
 fi;
 echo -e "${GREEN}[I]: Backing up Spack branch ${CYAN}${profile}${NC}";
 mkdir -p ${MS_TARG}/Backups/${profile};
 rsync -aI ${MS_TARG}/${profile}/ ${MS_TARG}/Backups/${profile}/;
 echo -e "${GREEN}[I]: Done${NC}";
 shift;
 shift
 ;;
 restore)
 local profile="$2";
 if [ ! -d "${MS_TARG}/Backups/${profile}" ]; then
 echo -e "${RED}[E]: Backup does not exist${NC}";
 return;
 fi;
 echo -e "${GREEN}[I]: Restoring Spack branch ${CYAN}${profile}${NC}";
 rsync -aI ${MS_TARG}/Backups/${profile}/ ${MS_TARG}/${profile}/;
 echo -e "${GREEN}[I]: Done${NC}";
 shift;
 shift
 ;;
 list)
 echo -e "${CYAN}$(ls ${MS_TARG} | sed "s~Backups~~g" | xargs | sed "s~ ~\n~g" | nl -s '. ' -w 1)${NC}";
 shift
 ;;
 listBackups)
 if [ ! -d "${MS_TARG}/Backups" ]; then
 echo -e "${RED}[E]: No backups available${NC}";
 return;
 fi;
 echo -e "${CYAN}$(ls ${MS_TARG}/Backups | nl -s '. ' -w 1)${NC}";
 shift
 ;;
 remove)
 local profile="$2";
 if ! _ms_helper_branchTest; then
 return;
 fi;
 if [ -n "${MS_CURR}" ] && [ ${MS_CURR} = ${profile} ]; then
 _ms_helper_resetEnv;
 fi;
 echo -e "${GREEN}[I]: Removing Spack branch ${CYAN}${profile}${NC}";
 rm -rf ${MS_TARG}/${profile};
 echo -e "${GREEN}[I]: Done${NC}";
 shift;
 shift
 ;;
 removeBackup)
 local profile="$2";
 if [ ! -d "${MS_TARG}/Backups/${profile}" ]; then
 echo -e "${RED}[E]: Backup does not exist${NC}";
 return;
 fi;
 echo -e "${GREEN}[I]: Removing branch backup ${CYAN}${profile}${NC}";
 rm -rf ${MS_TARG}/Backups/${profile};
 echo -e "${GREEN}[I]: Done${NC}";
 shift;
 shift
 ;;
 which)
 echo -e "${CYAN}${MS_CURR}${NC}";
 shift
 ;;
 cd)
 local profile="$2";
 if ! _ms_helper_branchTest; then
 return;
 fi;
 echo -e "${GREEN}[I]: Switching to ${CYAN}${profile}${NC}";
 cd ${MS_TARG}/${profile};
 echo -e "${GREEN}[I]: Done${NC}";
 shift;
 shift
 ;;
 pkgload)
 local profile="$2";
 local package="$3";
 if ! _ms_helper_branchTest; then
 return;
 fi;
 local precise_info=$(_ms_helper_load && spack find --format "{name}@{version}/{hash:7}%{compiler}" ${package});
 if ! _ms_helper_pkgTest; then
 return;
 fi;
 if [[ ! "${MS_PACKAGES}" =~ "${profile} ${precise_info}" ]]; then
 echo -e "${GREEN}[I]: Loading package ${CYAN}${profile} ${YELLOW}${precise_info}${NC}";
 export MS_PACKAGES="${profile} ${precise_info}:${MS_PACKAGES}";
 local package_path=$(_ms_helper_load && spack location -i "${precise_info}");
 if [[ ! "${MS_PATH}" =~ ${package_path} ]]; then
 export MS_PATH="${package_path}:${MS_PATH}";
 if ( [ -d "${package_path}/bin" ] || [ -L "${package_path}/bin" ] ) && [[ ! "${package_path}" == "/usr"* ]]; then
 export PATH="${package_path}/bin:$PATH";
 fi;
 if [ -d "${package_path}/lib" ] || [ -L "${package_path}/lib" ]; then
 export LD_LIBRARY_PATH="${package_path}/lib:$LD_LIBRARY_PATH";
 export MS_LDFLAGS="-L${package_path}/lib ${MS_LDFLAGS}";
 fi;
 if [ -d "${package_path}/lib64" ] || [ -L "${package_path}/lib64" ]; then
 export LD_LIBRARY_PATH="${package_path}/lib64:$LD_LIBRARY_PATH";
 export MS_LDFLAGS="-L${package_path}/lib64 ${MS_LDFLAGS}";
 fi;
 if [ -d "${package_path}/include" ] || [ -L "${package_path}/include" ]; then
 export MS_INCLUDE="-I${package_path}/include ${MS_INCLUDE}";
 fi;
 fi;
 local identifier=$(_ms_helper_load && spack find --format "{name}_{hash:7}" ${package});
 eval "export MS_${profile}_${identifier}_HOME=${package_path}";
 echo -e "${GREEN}[I]: Done${NC}";
 else
 echo -e "${YELLOW}[W]: Package already loaded${NC}";
 fi;
 shift;
 shift;
 shift
 ;;
 pkgunload)
 local profile="$2";
 local package="$3";
 if ! _ms_helper_branchTest; then
 return;
 fi;
 local precise_info=$(_ms_helper_load && spack find --format "{name}@{version}/{hash:7}%{compiler}" ${package});
 if ! _ms_helper_pkgTest; then
 return;
 fi;
 if [[ "${MS_PACKAGES}" =~ "${profile} ${precise_info}" ]]; then
 echo -e "${GREEN}[I]: Unloading package ${CYAN}${profile} ${YELLOW}${precise_info}${NC}";
 export MS_PACKAGES=$(echo ${MS_PACKAGES} | sed "s~${profile} ${precise_info}:~~g");
 local package_path=$(_ms_helper_load && spack location -i "${precise_info}");
 local prefix="${package_path}";
 _ms_helper_pkgunload;
 local identifier=$(_ms_helper_load && spack find --format "{name}_{hash:7}" ${package});
 eval "unset MS_${profile}_${identifier}_HOME";
 echo -e "${GREEN}[I]: Done${NC}";
 else
 echo -e "${YELLOW}[W]: Package has not been loaded${NC}";
 fi;
 shift;
 shift;
 shift
 ;;
 pkgunloadAll)
 echo -e "${GREEN}[I]: Unloading all packages${NC}";
 if [ -n "${MS_CURR}" ]; then
 spack unload -a;
 fi;
 while read -r info; do
 local arr=($info);
 local profile=${arr[0]};
 local package=${arr[1]};
 local identifier=$(_ms_helper_load && spack find --format "{name}_{hash:7}" ${package});
 eval "unset MS_${profile}_${identifier}_HOME";
 done < <(echo ${MS_PACKAGES} | grep -oP "\K.*?(?=:)");
 unset MS_PACKAGES;
 local prefix="${MS_TARG}";
 _ms_helper_pkgunload;
 while read -r prefix; do
 _ms_helper_pkgunload;
 done < <(echo ${MS_PATH} | grep -oP "\K.*?(?=:)");
 unset MS_PATH MS_INCLUDE MS_LDFLAGS;
 if [ -n "${MS_CURR}" ]; then
 export PATH=${MS_TARG}/${MS_CURR}/spack/bin:$PATH;
 fi;
 echo -e "${GREEN}[I]: Done${NC}";
 shift
 ;;
 pkglistLoaded)
 if [ -n "${MS_PACKAGES}" ]; then
 echo -e "${CYAN}$(echo ${MS_PACKAGES::-1} | sed "s~:~\n~g" | nl -s '. ' -w 1)${NC}";
 fi;
 shift
 ;;
 pkginstall)
 local profile="$2";
 local package="$3";
 if [ -n "${MS_CURR}" ]; then
 echo -e "${YELLOW}[W]: Active branch ${CYAN}${MS_CURR}${YELLOW} detected${NC}";
 echo -e "${RED}[E]: Environment not clean enough${NC}";
 return;
 fi;
 if ! _ms_helper_branchTest; then
 return;
 fi;
 ( _ms_helper_load && spack install -j32 ${package} );
 shift;
 shift;
 shift
 ;;
 envinstall)
 local profile="$2";
 local envPath="$3";
 if [ -n "${MS_CURR}" ]; then
 echo -e "${YELLOW}[W]: Active branch ${CYAN}${MS_CURR}${YELLOW} detected${NC}";
 echo -e "${RED}[E]: Environment not clean enough${NC}";
 return;
 fi;
 if ! _ms_helper_branchTest; then
 return;
 fi;
 if [ ! -d "${envPath}" ] || [ ! -f "${envPath}/spack.yaml" ]; then
 echo -e "${RED}[E]: Environment does not exist${NC}";
 return;
 fi;
 rm -rf ${envPath}/spack.lock;
 rm -rf ${envPath}/.spack-env;
 ( _ms_helper_load && spack env activate ${envPath} && spack concretize -j32 -f && spack install -j32 && spack env deactivate );
 rm -rf ${envPath}/spack.lock;
 rm -rf ${envPath}/.spack-env;
 shift;
 shift;
 shift
 ;;
 pkguninstall)
 local profile="$2";
 local package="$3";
 if ! _ms_helper_branchTest; then
 return;
 fi;
 local precise_info=$(_ms_helper_load && spack find --format "{name}@{version}/{hash:7}%{compiler}" ${package});
 if ! _ms_helper_pkgTest; then
 return;
 fi;
 ( _ms_helper_load && spack uninstall ${package} );
 shift;
 shift;
 shift
 ;;
 pkglocate)
 local profile="$2";
 local package="$3";
 if ! _ms_helper_branchTest; then
 return;
 fi;
 local precise_info=$(_ms_helper_load && spack find --format "{name}@{version}/{hash:7}%{compiler}" ${package});
 if ! _ms_helper_pkgTest; then
 return;
 fi;
 ( _ms_helper_load && spack location -i ${package} );
 shift;
 shift;
 shift
 ;;
 shell)
 local profile="$2";
 local command="$3";
 if ! _ms_helper_branchTest; then
 return;
 fi;
 ( _ms_helper_load && eval "${command}" );
 shift;
 shift;
 shift
 ;;
 test)
 echo -e "${GREEN}[I]: Welcome to the secret test function${NC}";
 shift
 ;;
 *)
 echo -e "${RED}[E]: Unexpected option $1${NC}";
 return
 ;;
 esac;
 done
}

environment.BASH_FUNC__ms_helper_resetEnv%%:
() {  if [ -n "${MS_CURR}" ]; then
 spack unload -a;
 unset -f spack _spack_shell_wrapper;
 unset SPACK_PYTHON SPACK_ROOT;
 unset SPACK_USER_CACHE_PATH;
 unalias spacktivate;
 local prefix="${MS_TARG}/${MS_CURR}";
 _ms_helper_pkgunload;
 unset MS_CURR;
 fi
}

environment.BASH_FUNC__ms_helper_pkgTest%%:
() {  if [ -z "${precise_info}" ]; then
 echo -e "${RED}[E]: Package does not exist${NC}";
 return -1;
 fi;
 if [[ "${precise_info}" =~ [[:space:]] ]]; then
 echo -e "${RED}[E]: Multiple packages found${NC}";
 return -1;
 fi
}

environment.BASH_FUNC__ms_helper_load%%:
() {  export SPACK_DISABLE_LOCAL_CONFIG=true;
 export SPACK_USER_CACHE_PATH=${MS_TARG}/${profile}/.spack;
 source ${MS_TARG}/${profile}/spack/share/spack/setup-env.sh;
 export MS_CURR=${profile}
}

environment.BASH_FUNC__ms_helper_pkgunload%%:
() {  if [[ "$prefix" == "/usr"* ]]; then
 return;
 fi;
 local tmp;
 tmp=$PATH;
 while read -r line; do
 tmp=$(echo ${tmp} | sed "s~${prefix}${line}:~~g");
 done < <(echo ${PATH} | grep -oP "${prefix}\K.*?(?=:)");
 export PATH=$tmp;
 tmp=$LD_LIBRARY_PATH;
 while read -r line; do
 tmp=$(echo ${tmp} | sed "s~${prefix}${line}:~~g");
 done < <(echo ${LD_LIBRARY_PATH} | grep -oP "${prefix}\K.*?(?=:)");
 export LD_LIBRARY_PATH=$tmp;
 tmp="";
 for line in ${MS_LDFLAGS};
 do
 if [[ ! "$line" == "-L${prefix}"* ]]; then
 tmp+="$line ";
 fi;
 done;
 export MS_LDFLAGS=$tmp;
 tmp="";
 for line in ${MS_INCLUDE};
 do
 if [[ ! "$line" == "-I${prefix}"* ]]; then
 tmp+="$line ";
 fi;
 done;
 export MS_INCLUDE=$tmp;
 tmp=$PKG_CONFIG_PATH_modshare;
 while read -r line; do
 tmp=$(echo ${tmp} | sed "s~${prefix}${line}:1:~~g");
 tmp=$(echo ${tmp} | sed "s~${prefix}${line}:1~~g");
 done < <(echo ${PKG_CONFIG_PATH_modshare} | grep -oP "${prefix}\K.*?(?=:1)");
 export PKG_CONFIG_PATH_modshare=$tmp;
 tmp=$MANPATH_modshare;
 while read -r line; do
 tmp=$(echo ${tmp} | sed "s~${prefix}${line}:1:~~g");
 tmp=$(echo ${tmp} | sed "s~${prefix}${line}:1~~g");
 done < <(echo ${MANPATH_modshare} | grep -oP "${prefix}\K.*?(?=:1)");
 export MANPATH_modshare=$tmp;
 tmp=$PATH_modshare;
 while read -r line; do
 tmp=$(echo ${tmp} | sed "s~${prefix}${line}:1:~~g");
 tmp=$(echo ${tmp} | sed "s~${prefix}${line}:1~~g");
 done < <(echo ${PATH_modshare} | grep -oP "${prefix}\K.*?(?=:1)");
 export PATH_modshare=$tmp;
 tmp=${MS_PATH};
 while read -r line; do
 tmp=$(echo ${tmp} | sed "s~${prefix}${line}:~~g");
 done < <(echo ${MS_PATH} | grep -oP "${prefix}\K.*?(?=:)");
 export MS_PATH=$tmp;
 export MS_PATH=$(echo ${MS_PATH} | sed "s~${prefix}:~~g")
}

environment.BASH_FUNC__module_raw%%:
() {  unset _mlshdbg;
 if [ "${MODULES_SILENT_SHELL_DEBUG:-0}" = '1' ]; then
 case "$-" in 
 *v*x*)
 set +vx;
 _mlshdbg='vx'
 ;;
 *v*)
 set +v;
 _mlshdbg='v'
 ;;
 *x*)
 set +x;
 _mlshdbg='x'
 ;;
 *)
 _mlshdbg=''
 ;;
 esac;
 fi;
 unset _mlre _mlIFS;
 if [ -n "${IFS+x}" ]; then
 _mlIFS=$IFS;
 fi;
 IFS=' ';
 for _mlv in ${MODULES_RUN_QUARANTINE:-};
 do
 if [ "${_mlv}" = "${_mlv##*[!A-Za-z0-9_]}" -a "${_mlv}" = "${_mlv#[0-9]}" ]; then
 if [ -n "`eval 'echo ${'$_mlv'+x}'`" ]; then
 _mlre="${_mlre:-}${_mlv}_modquar='`eval 'echo ${'$_mlv'}'`' ";
 fi;
 _mlrv="MODULES_RUNENV_${_mlv}";
 _mlre="${_mlre:-}${_mlv}='`eval 'echo ${'$_mlrv':-}'`' ";
 fi;
 done;
 if [ -n "${_mlre:-}" ]; then
 eval `eval ${_mlre} /usr/bin/tclsh /cm/local/apps/environment-modules/4.5.3/libexec/modulecmd.tcl bash '"$@"'`;
 else
 eval `/usr/bin/tclsh /cm/local/apps/environment-modules/4.5.3/libexec/modulecmd.tcl bash "$@"`;
 fi;
 _mlstatus=$?;
 if [ -n "${_mlIFS+x}" ]; then
 IFS=$_mlIFS;
 else
 unset IFS;
 fi;
 unset _mlre _mlv _mlrv _mlIFS;
 if [ -n "${_mlshdbg:-}" ]; then
 set -$_mlshdbg;
 fi;
 unset _mlshdbg;
 return $_mlstatus
}

environment.BASH_FUNC__ms_helper_branchTest%%:
() {  if [ ! -d "${MS_TARG}/${profile}" ]; then
 echo -e "${RED}[E]: Branch does not exist${NC}";
 return -1;
 fi
}
